 */
char* parse_hname2_short(char* const begin, const char* const end, struct hdr_field* const hdr)
{
        return parse_sip_header_name(begin, end, hdr, 0, 1);
}

char* parse_hname2_str (str* const hbuf, hdr_field_t* const hdr)
{
