}


/* returns pointer to next header line, and fill hdr_f ;
 * if at end of header returns pointer to the last crlf  (always buf)*/
char* get_hdr_field(char* const buf, char* const end, struct hdr_field* const hdr)
{

        char *tmp = 0;
        char *match;
        struct via_body *vb;
        struct cseq_body* cseq_b;
        struct to_body* to_b;
        int integer, err;
        unsigned uval;

        if(!buf) {
                DBG("null buffer pointer\n");
                goto error;
        }

        if ((*buf)=='\n' || (*buf)=='\r'){
                /* double crlf or lflf or crcr */
                DBG("found end of header\n");
                hdr->type=HDR_EOH_T;
                return buf;
        }

        tmp=parse_hname(buf, end, hdr);
        if (hdr->type==HDR_ERROR_T){
                ERR("bad header\n");
                goto error;
        }

        /* eliminate leading whitespace */
        tmp=eat_lws_end(tmp, end);
        if (tmp>=end) {
                ERR("HF empty\n");
                goto error;
        }

        /* if header-field well-known, parse it, find its end otherwise ;
         * after leaving the hdr->type switch, tmp should be set to the
         * next header field
         */
        switch(hdr->type){
                case HDR_VIA_T:
                        /* keep number of vias parsed -- we want to report it in
                           replies for diagnostic purposes */
                        via_cnt++;
                        vb=pkg_malloc(sizeof(struct via_body));
                        if (vb==0){
                                PKG_MEM_ERROR;
                                goto error;
                        }
                        memset(vb,0,sizeof(struct via_body));
                        hdr->body.s=tmp;
                        tmp=parse_via(tmp, end, vb);
                        if (vb->error==PARSE_ERROR){
                                ERR("bad via\n");
                                free_via_list(vb);
                                goto error;
                        }
